379	+                                   (left instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
380	+          final String rightTitle = right.getRevisionNumber().asString() +
381	+                                    (right instanceof CurrentRevision ? " (" + VcsBundle.message("diff.title.local") + ")" : "");
382	+          showDiff(project, filePath, left, right, leftTitle, rightTitle);
383	+        }
