106	+public class CancelHelper implements Disposable, Processor<Thread> {
107	+  private final Map<ProgressIndicator, Thread> myMap;
108	+  private final Set<Thread> myInterrupted;
109	+  private MessageBusConnection myConnection;
110	+  private final Object myLock;
111	+
112	+  public CancelHelper(final Project project) {
113	+    myMap = new HashMap<ProgressIndicator, Thread>();
114	+    myLock = new Object();
115	+    myInterrupted = new HashSet<Thread>();
116	+    myConnection = project.getMessageBus().connect(project);
117	+    myConnection.subscribe(ProgressManager.CANCEL_CALLED, new Runnable() {
118	+      @Override
119	+      public void run() {
120	+        synchronized (myLock) {
121	+          for (Map.Entry<ProgressIndicator, Thread> entry : myMap.entrySet()) {
122	+            if (entry.getKey().isCanceled()) {
123	+              myInterrupted.add(entry.getValue());
124	+            }
125	+          }
126	+        }
127	+      }
128	+    });
129	+  }
130	+
131	+  public static CancelHelper getInstance(final Project project) {
132	+    return project.getComponent(CancelHelper.class);
133	+  }
134	+
135	+  /**
136	+   * @return false if process was canceled
137	+   */
138	+  @Override
139	+  public boolean process(Thread thread) {
140	+    synchronized (myLock) {
141	+      return ! myInterrupted.contains(thread);
142	+    }
143	+  }
144	+
145	+  @Override
146	+  public void dispose() {
147	+    myConnection.disconnect();
148	+    myConnection = null;
149	+  }
150	+
151	+  public Runnable proxyRunnable(final Runnable runnable) {
152	+    return new Runnable() {
153	+      @Override
154	+      public void run() {
155	+        ProgressIndicator indicator = ProgressManager.getInstance().getProgressIndicator();
156	+        if (indicator == null) {
157	+          runnable.run();
158	+          return;
159	+        }
160	+        try {
161	+          synchronized (myLock) {
162	+            myMap.put(indicator, Thread.currentThread());
163	+          }
164	+          runnable.run();
165	+        } finally {
166	+          synchronized (myLock) {
167	+            myInterrupted.remove(Thread.currentThread());
168	+            myMap.remove(indicator);
169	+          }
170	+        }
171	+      }
172	+    };
173	+  }
174	+
175	+  public Task proxyTask(final Task task) {
176	+    if (task instanceof Task.Backgroundable) {
177	+      return new Task.Backgroundable(task.getProject(), task.getTitle(), task.isCancellable()) {
178	+        @Override
179	+        public void run(@NotNull ProgressIndicator indicator) {
180	+          runTask(indicator, task);
181	+        }
182	+
183	+        public void onCancel() {
184	+          task.onCancel();
185	+        }
186	+
187	+        public void onSuccess() {
188	+          task.onSuccess();
189	+        }
190	+
191	+        public String getProcessId() {
192	+          return task.getProcessId();
193	+        }
194	+
195	+        @Nullable
196	+        public NotificationInfo getNotificationInfo() {
197	+          return task.getNotificationInfo();
198	+        }
199	+
200	+        @Nullable
201	+        public NotificationInfo notifyFinished() {
202	+          return task.notifyFinished();
203	+        }
204	+
205	+        public boolean isHeadless() {
206	+          return task.isHeadless();
207	+        }
208	+      };
209	+    } else {
210	+      return new Task(task.getProject(), task.getTitle(), task.isCancellable()) {
211	+        @Override
212	+        public boolean isModal() {
213	+          return task.isModal();
214	+        }
215	+
216	+        @Override
217	+        public void onCancel() {
218	+          task.onCancel();
219	+        }
220	+
221	+        @Override
222	+        public void onSuccess() {
223	+          task.onSuccess();
224	+        }
225	+
226	+        @Override
227	+        public String getProcessId() {
228	+          return task.getProcessId();
229	+        }
230	+
231	+        @Override
232	+        public NotificationInfo getNotificationInfo() {
233	+          return task.getNotificationInfo();
234	+        }
235	+
236	+        @Override
237	+        public NotificationInfo notifyFinished() {
238	+          return task.notifyFinished();
239	+        }
240	+
241	+        @Override
242	+        public boolean isHeadless() {
243	+          return task.isHeadless();
244	+        }
245	+
246	+        @Override
247	+        public void run(@NotNull ProgressIndicator indicator) {
248	+          runTask(indicator, task);
249	+        }
250	+      };
251	+    }
252	+  }
253	+
254	+  private void runTask(ProgressIndicator indicator, Task task) {
255	+    try {
256	+      synchronized (myLock) {
257	+        myMap.put(indicator, Thread.currentThread());
258	+      }
259	+      task.run(indicator);
260	+    } finally {
261	+      synchronized (myLock) {
262	+        myInterrupted.remove(Thread.currentThread());
263	+        myMap.remove(indicator);
264	+      }
265	+    }
266	+  }
